// The list endpoint returns totals already computed, so nothing is recalculated here.
// A non-financial document (a delivery note) returns null totals rather than zero and is
// left out of the sum instead of pulling it down.
const invoices = $input.all().map((i) => i.json);
const money = (v) => (v === null || v === undefined ? null : Number(v));
const gross = invoices.map((inv) => money(inv.totalGross)).filter((v) => v !== null);
const total = gross.reduce((s, v) => s + v, 0);

// status is a relation on the document, so it arrives as an object when it is loaded at all.
const label = (s) => (typeof s === 'string' ? s : (s && s.name) || 'Without status');
const byStatus = {};
for (const inv of invoices) {
  const k = label(inv.status);
  byStatus[k] = (byStatus[k] || 0) + 1;
}

const fmt = (v) =>
  v === null ? '-' : v.toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' \u20ac';
const rows = invoices
  .slice(0, 25)
  .map(
    (inv) =>
      `<tr><td>${inv.invoiceNumber ?? '-'}</td><td>${inv.title ?? '-'}</td><td>${label(inv.status)}</td>` +
      `<td style="text-align:right">${fmt(money(inv.totalGross))}</td></tr>`,
  )
  .join('');

const html = `<h2>cashwerk \u2013 daily invoice summary</h2>
<p><b>${invoices.length}</b> invoices \u00b7 total <b>${fmt(total)}</b></p>
<p>${Object.entries(byStatus).map(([k, v]) => `${k}: ${v}`).join(' \u00b7 ')}</p>
<table border="1" cellpadding="6" style="border-collapse:collapse">
<tr><th>Number</th><th>Title</th><th>Status</th><th>Gross</th></tr>${rows}</table>`;

return [{ json: { html, count: invoices.length, totalGross: total } }];
